export const formatVND = (amount: number): string => {
  if (amount >= 1000000) {
    return `${(amount / 1000000).toFixed(1)}M₫`;
  }
  return `${(amount / 1000).toFixed(0)}k₫`;
};

export const getRiskColor = (risk: "low" | "medium" | "high") => {
  switch (risk) {
    case "low": return "text-emerald-400";
    case "medium": return "text-amber-400";
    case "high": return "text-red-400";
  }
};

export const getRiskBg = (risk: "low" | "medium" | "high") => {
  switch (risk) {
    case "low": return "bg-emerald-500/10 border-emerald-500/30";
    case "medium": return "bg-amber-500/10 border-amber-500/30";
    case "high": return "bg-red-500/10 border-red-500/30";
  }
};

export const getRecommendationLabel = (rec: string) => {
  switch (rec) {
    case "buy_now": return "MUA NGAY";
    case "wait": return "CHỜ THÊM";
    case "skip": return "BỎ QUA";
    default: return rec;
  }
};

export const getRecommendationColor = (rec: string) => {
  switch (rec) {
    case "buy_now": return "bg-emerald-500 text-white";
    case "wait": return "bg-amber-500 text-white";
    case "skip": return "bg-red-500 text-white";
    default: return "bg-slate-500 text-white";
  }
};

